INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,1,'1. 二〇二六年五月、青嶺町の「灯窯工房」で、職人の真鍋澄江は参加者が使う小刀の柄を一つずつ拵えておいた。','1. 二〇二六年五月、青嶺町の「灯窯工房」で、職人の真鍋澄江は参加者が使う小刀の柄を一つずつ<u>拵えて</u>おいた。',1,NULL,1.00,NULL,'「拵えて」は、道具などを工夫して作るという意味の「こしらえる」の活用形なので、読みは「こしらえて」です。',1);
INSERT INTO jlpt_option(question_id,option_number,option_text,order_index) VALUES (@mock_question_id,1,'こしらえて',1);
INSERT INTO jlpt_option(question_id,option_number,option_text,order_index) VALUES (@mock_question_id,2,'こらえて',2);
