INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,3,'3. 二〇二六年九月二十二日、月見野町の秋季祭では、古式にのっとった神事が午前六時から斎行された。','3. 二〇二六年九月二十二日、月見野町の秋季祭では、古式にのっとった神事が午前六時から<u>斎行された</u>。',2,NULL,1.00,NULL,'「斎行」は祭りや儀式を厳粛に執り行うことで、ここでは「さいこうされた」と読みます。',3);
