INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,6,'6. 星浦八幡宮の例大祭が終わると、氏子たちは社務所に集まり、神前に供えた酒や料理を分かち合う直会に移った。','6. 星浦八幡宮の例大祭が終わると、氏子たちは社務所に集まり、神前に供えた酒や料理を分かち合う<u>直会</u>に移った。',3,NULL,1.00,NULL,'「直会」は祭礼後に供物を参列者が共に飲食する行事で、読みは「なおらい」です。',6);
