INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,11,'11. 青葉県の港町・汐見で開かれた「海鳴り市」では、人気料理人の出店を目当てに例年以上の人出があった。その人気に（　）した臨時店が相次ぎ、商店街では通行の妨げを懸念する声も出た。','11. 青葉県の港町・汐見で開かれた「海鳴り市」では、人気料理人の出店を目当てに例年以上の人出があった。その人気に（　）した臨時店が相次ぎ、商店街では通行の妨げを懸念する声も出た。',4,NULL,1.00,NULL,'「便乗する」は、他の人気や好機を利用して利益を得ようとすることで、祭りの集客力を利用した臨時店に適する。',5);
