INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,12,'12. 北雲市立「ことり文庫」では、利用者の要望を受けて夜間開館の導入を検討している。いきなり本格導入するのではなく、2030年1月から三か月間（　）し、利用状況を検証する方針だ。','12. 北雲市立「ことり文庫」では、利用者の要望を受けて夜間開館の導入を検討している。いきなり本格導入するのではなく、2030年1月から三か月間（　）し、利用状況を検証する方針だ。',1,NULL,1.00,NULL,'「試行する」は、本格的に実施する前に試しに行うという意味で、三か月間の実験的な夜間開館に合う。',6);
