INSERT INTO jlpt_mondai(part_id,mondai_number,format_code,instruction_html,audio_url,order_index) VALUES (@mock_part_id,3,'paraphrase','問題3：下線の言葉と意味が最も近いものを一つ選びなさい。',NULL,3);
INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,14,'14. 青波町の「硝子工芸舎」では、二〇二七年六月の灯籠祭に向け、若手職人の蓮見透が師匠から制作の心得を学んでいた。師匠は「観光客向けの品だからといって手を抜かず、腕によりをかけることを忘れるな」と念を押した。この表現と最も近い意味のものはどれか。','14. 青波町の「硝子工芸舎」では、二〇二七年六月の灯籠祭に向け、若手職人の蓮見透が師匠から制作の心得を学んでいた。師匠は「観光客向けの品だからといって手を抜かず、<u>腕によりをかける</u>ことを忘れるな」と念を押した。この表現と最も近い意味のものはどれか。',1,NULL,1.00,NULL,'「腕によりをかける」は、自分の技術を最大限に生かして心を込めて仕上げるという意味です。',1);
INSERT INTO jlpt_option(question_id,option_number,option_text,order_index) VALUES (@mock_question_id,1,'持てる技術を十分に発揮して、丹念に仕上げる',1);
