INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,15,'15. 白瀬市立みなと中央図書館では、二〇二六年九月から郷土資料の閲覧方法を見直すことになった。利用者代表の久我真帆は、保存を優先しすぎる案について「せっかく利用者同士の理解が深まりつつあるのに、規則を一方的に増やすのは議論に水を差すのではないか」と発言した。この表現と最も近い意味のものはどれか。','15. 白瀬市立みなと中央図書館では、二〇二六年九月から郷土資料の閲覧方法を見直すことになった。利用者代表の久我真帆は、保存を優先しすぎる案について「せっかく利用者同士の理解が深まりつつあるのに、規則を一方的に増やすのは議論に<u>水を差す</u>のではないか」と発言した。この表現と最も近い意味のものはどれか。',2,NULL,1.00,NULL,'「水を差す」は、順調に進んでいる物事の勢いや雰囲気を損なうという意味です。',2);
INSERT INTO jlpt_option(question_id,option_number,option_text,order_index) VALUES (@mock_question_id,1,'議論の焦点を別の問題へ移す',1);
