INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,15,'15. 水梧町の自治会は、毎年六月の地域リサイクル行事で回収した資源の一部に異物が混じることを問題視していた。今年は回収場所を増やすだけでなく、素材ごとの見本を掲示し、係員がその場で確認する仕組みを導入して分別の徹底を図ることにした。「分別の徹底を図る」の意味に最も近いものはどれか。','15. 水梧町の自治会は、毎年六月の地域リサイクル行事で回収した資源の一部に異物が混じることを問題視していた。今年は回収場所を増やすだけでなく、素材ごとの見本を掲示し、係員がその場で確認する仕組みを導入して<u>分別の徹底を図る</u>ことにした。「分別の徹底を図る」の意味に最も近いものはどれか。',4,NULL,1.00,NULL,'「分別の徹底を図る」は、分別が十分に行われるよう対策を講じるという意味なので、4が正しい。',2);
INSERT INTO jlpt_option(question_id,option_number,option_text,order_index) VALUES (@mock_question_id,1,'分別作業を一時的に取りやめる',1);
