INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,@mock_passage_2,NULL,8,'8. 「春川まちの循環市」が今年、前年より回収量を増やすことだけを目的にしなかったのはなぜか。','8. 「春川まちの循環市」が今年、前年より回収量を増やすことだけを目的にしなかったのはなぜか。',2,NULL,3.00,NULL,'今年の目的は分別の理由を理解して日常の廃棄物も減らすことであり、回収量の増加だけではなかったため2が正しい。',4);
