INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,@mock_passage_3,NULL,11,'11. 水野が浜守味噌について「伝統を守る」ために必要だと考えているのは、どのようなことか。','11. 水野が浜守味噌について「伝統を守る」ために必要だと考えているのは、どのようなことか。',3,NULL,3.00,NULL,'水野は地元の原料や麹など受け継ぐ核心を明確にしつつ用途に応じた商品を作ることを伝統の継承と考えているため3が正しい。',7);
