INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,1,'1. 朝凪町の刀鍛冶工房「青嵐」で、見習いの柊真は師匠の技を受け継ごうと、日々研鑽を重ねている。','1. 朝凪町の刀鍛冶工房「青嵐」で、見習いの柊真は師匠の技を受け継ごうと、日々<u>研鑽</u>を重ねている。',1,NULL,1.00,NULL,'「研鑽」は、khi nói về việc không ngừng học hỏi và rèn luyện để nâng cao kỹ năng, được đọc là 「けんさん」.',1);
