INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,7,'7. 岐阜県白嶺町の木工房で修業を始めた佐伯は、師匠が鉋を動かす角度や力加減を（　）観察し、同じ道具でも扱い方次第で仕上がりが変わることを学んだ。','7. 岐阜県白嶺町の木工房で修業を始めた佐伯は、師匠が鉋を動かす角度や力加減を（　）観察し、同じ道具でも扱い方次第で仕上がりが変わることを学んだ。',1,NULL,1.00,NULL,'「つぶさに」は細部まで詳しくという意味で、師匠の動作を注意深く観察する文脈に適している。',1);
