INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,12,'12. 東浦町のバス再編をめぐり、自治体は運行会社だけでなく学校や病院とも協議を重ね、通学・通院の実態と経費の両面を踏まえて運行計画を（　）ことにした。','12. 東浦町のバス再編をめぐり、自治体は運行会社だけでなく学校や病院とも協議を重ね、通学・通院の実態と経費の両面を踏まえて運行計画を（　）ことにした。',3,NULL,1.00,NULL,'「すり合わせる」は複数の意見や条件を調整して一致点を見いだすという意味で、運行計画の調整に合う。',6);
