INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,13,'13. 青沼市立歴史館の特別展は予想を上回る来館者を集めたが、学芸員の黒川は、その盛況を目新しさだけに（　）するのは早計だと考えている。','13. 青沼市立歴史館の特別展は予想を上回る来館者を集めたが、学芸員の黒川は、その盛況を目新しさだけに（　）するのは早計だと考えている。',1,NULL,1.00,NULL,'「帰する」は結果や原因をあるものに結びつけて説明するという意味で、盛況の原因を目新しさだけに求める文脈に適している。',7);
