INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,14,'14. 長野県青波町の漆器工房では、見習いの久瀬莉央が師匠の榊原玄一から木地の扱いを学んでいる。莉央は道具の使い方こそ覚えたものの、塗りの厚さを均一にする感覚までは身についておらず、いまだに見よう見まねの域を出ない。この表現の意味として最も近いものはどれか。','14. 長野県青波町の漆器工房では、見習いの久瀬莉央が師匠の榊原玄一から木地の扱いを学んでいる。莉央は道具の使い方こそ覚えたものの、塗りの厚さを均一にする感覚までは身についておらず、いまだに<u>見よう見まねの域を出ない</u>。この表現の意味として最も近いものはどれか。',2,NULL,1.00,NULL,'「見よう見まねの域を出ない」は、他人のやり方をまねているだけで、まだ十分に習得できていないという意味です。',1);
