INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,15,'15. 山梨県水鏡市では、赤字が続く市営バスの路線を見直すため、住民説明会が開かれた。利用者の少ない朝倉峠線について、市の担当者は「高齢者の通院手段を守るため、当面は採算を度外視して運行を続ける」と説明した。この表現の意味として最も近いものはどれか。','15. 山梨県水鏡市では、赤字が続く市営バスの路線を見直すため、住民説明会が開かれた。利用者の少ない朝倉峠線について、市の担当者は「高齢者の通院手段を守るため、当面は<u>採算を度外視して</u>運行を続ける」と説明した。この表現の意味として最も近いものはどれか。',4,NULL,1.00,NULL,'「採算を度外視して」は、利益が得られるかどうかを考慮せずに実施するという意味です。',2);
INSERT INTO jlpt_option(question_id,option_number,option_text,order_index) VALUES (@mock_question_id,1,'利益が出る可能性を詳しく検討したうえで',1);
