INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,16,'16. 青波県立民俗資料館では、明治期の養蚕農家で使われていた道具を紹介する特別展を開催している。なかでも、現存例が少ない手織り機の実演映像は来館者の関心を集め、館長はこれを展示の目玉として広報の中心に据えた。この表現の意味として最も近いものはどれか。','16. 青波県立民俗資料館では、明治期の養蚕農家で使われていた道具を紹介する特別展を開催している。なかでも、現存例が少ない手織り機の実演映像は来館者の関心を集め、館長はこれを<u>展示の目玉</u>として広報の中心に据えた。この表現の意味として最も近いものはどれか。',1,NULL,1.00,NULL,'「展示の目玉」は、展示の中で特に人の注目を集める中心的な資料や企画を指します。',3);
INSERT INTO jlpt_option(question_id,option_number,option_text,order_index) VALUES (@mock_question_id,1,'展示の中で、特に注目を集める中心的な資料や企画',1);
