INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,20,'20. 立ち行く','20. 立ち行く',2,NULL,1.00,NULL,'「立ち行く」は事業や制度などがなんとか成り立つという意味で、利用者減少によって路線が維持できなくなるという文脈に適しています。',1);
