INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,1,'石川県南部の架空の港町・汐見町では、二〇二六年春から秋にかけて、伝統工芸、公共交通、博物館、地域行事を連動させた試みが行われた。きっかけは、青波焼の窯元である蓮見陶房が、町外から来た十九歳の水城澪を【1】ことにしたことである。師匠の蓮見宗一は、技法を一方的に教え込むのではなく、土の採取から窯の手入れまでを本人に担わせ、失敗の記録も残すよう求めた。
