INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,8,'長野県北部の架空の町、霧野町では、かつて盛んだった木工業と山間部の交通をどう次世代へ引き継ぐかが、ここ数年の課題となっている。町の中心から工房の集まる谷間まで走る霧野町営バスは、利用者の減少を理由に、二〇二四年四月から一日六便を四便に減らす予定だった。ところが、木工職人の三枝玄一が弟子の相原美緒とともに町へ提出した提案書は、単なる増便の要望ではなかった。二人は、バスの乗客を増やすために観光客を呼び込むのではなく、工房、町立博物館、祭りを一つの生活圏として捉え直すべきだと主張したのである。
INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,@mock_passage_1,NULL,14,'14. 三枝が町営バスの増便を求める提案書で、単なる増便の要望にとどめなかったのはなぜか。','14. 三枝が町営バスの増便を求める提案書で、単なる増便の要望にとどめなかったのはなぜか。',2,NULL,3.00,NULL,'三枝は観光客の誘致だけでなく、工房・博物館・祭りを住民の生活圏として結び、日常利用によってバスを存続させようとしたからです。',1);
