INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,@mock_passage_1,NULL,18,'18. 事務局の案を実施可能なものにするために、最も適切に修正したものはどれか。','18. 事務局の案を実施可能なものにするために、最も適切に修正したものはどれか。',3,NULL,3.00,NULL,'Phương án 3 tuân thủ đồng thời quy định bảo tồn của bảo tàng, điều kiện đăng ký và giám sát tại xưởng, cũng như hạn chế về xe buýt và nhân lực tình nguyện.',1);
INSERT INTO jlpt_option(question_id,option_number,option_text,order_index) VALUES (@mock_question_id,1,'資料館での実演を取りやめ、工房での実演を当日受付に変更したうえで、帰りは参加者の人数に応じて臨時車両を手配する。',1);
