INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,24,'24. 桜野市立ひかり図書館では、郷土資料室の改修に関する案内を2026年5月3日に掲示した。司書の水城さんは、利用者から質問される可能性があるため、職員全員にその案内へ目を通しておくよう伝えた。ここで「目を通す」とは、どのような意味か。','24. 桜野市立ひかり図書館では、郷土資料室の改修に関する案内を2026年5月3日に掲示した。司書の水城さんは、利用者から質問される可能性があるため、職員全員にその案内へ<u>目を通して</u>おくよう伝えた。ここで「目を通す」とは、どのような意味か。',4,NULL,1.00,NULL,'「目を通す」は、文章などを最初から最後までひととおり読んで確認するという意味です。',2);
