INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,9,'青波町では、11月16日（土）に「秋灯り週間」の催しが行われる。潮風工芸館では10時から12時まで、12歳以上を対象にした木版画の体験教室が開かれるが、参加には11月10日までの予約が必要である。教室から徒歩10分の青波町立図書館では、13時から14時まで郷土作家の講演会が開かれる。講演会は予約不要だが、席がなくなり次第締め切られ、入場できるのは13時10分までである。祭りの中心となる「秋灯り祭」は14時30分から16時30分まで川辺広場で行われる。星川駅から青波駅までは、この日だけ運行される列車が8時20分に出発し、9時15分に到着する。帰りの列車は17時40分発で、星川駅には18時35分に着く。参加者の予定は次のとおりである。ユキは木版画教室を予約しており、祭りの後も急ぐ必要はない。エリは教室を予約しているが、16時20分までに町を出なければならない。マサトは教室を予約していないものの、講演会と祭りには参加したいと考えている。','青波町では、11月16日（土）に「秋灯り週間」の催しが行われる。潮風工芸館では10時から12時まで、12歳以上を対象にした木版画の体験教室が開かれるが、参加には11月10日までの予約が必要である。教室から徒歩10分の青波町立図書館では、13時から14時まで郷土作家の講演会が開かれる。講演会は予約不要だが、席がなくなり次第締め切られ、入場できるのは13時10分までである。祭りの中心となる「秋灯り祭」は14時30分から16時30分まで川辺広場で行われる。星川駅から青波駅までは、この日だけ運行される列車が8時20分に出発し、9時15分に到着する。帰りの列車は17時40分発で、星川駅には18時35分に着く。参加者の予定は次のとおりである。ユキは木版画教室を予約しており、祭りの後も急ぐ必要はない。エリは教室を予約しているが、16時20分までに町を出なければならない。マサトは教室を予約していないものの、講演会と祭りには参加したいと考えている。',NULL,9);
INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,@mock_passage_1,NULL,15,'15. 三人の予定のうち、案内の条件に合っているものはどれか。','15. 三人の予定のうち、案内の条件に合っているものはどれか。',2,NULL,3.00,NULL,'ユキは教室を予約済みで、講演会の開始時刻にも間に合い、祭りの後に17時40分発の列車で帰れるためです。',1);
