INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,@mock_passage_1,NULL,16,'16. 図書館員がマサトに伝える内容として、最も適切なものはどれか。','16. 図書館員がマサトに伝える内容として、最も適切なものはどれか。',4,NULL,3.00,NULL,'マサトは教室を予約していないため参加できませんが、予約不要の講演会と14時30分からの祭りには参加できるからです。',2);
