INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,12,'月見野市の藍川朝市は、毎月第2土曜日に開かれる。約40年前、近くの農家が余った野菜や手作りの保存食を売ったことから始まり、現在では市外からも客が訪れる。名物の「ひなた団子」は、地元で栽培される雑穀を使い、店ごとに甘さや焼き方が少しずつ違う。朝市では、商品を並べるだけでなく、生産者が材料の収穫時期や家庭での食べ方を説明する時間も設けている。
INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,@mock_passage_1,NULL,17,'17. 自然観察ガイドに参加するために、前日までに必ずしなければならないことは何か。','17. 自然観察ガイドに参加するために、前日までに必ずしなければならないことは何か。',1,NULL,3.00,NULL,'Đoạn văn nói rõ người muốn tham gia phải đăng ký qua điện thoại hoặc trang web trước 17 giờ ngày hôm trước.',1);
