INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,1,'1. 二〇二七年四月、青波町の木工房で、佐伯蓮さんは師匠に教わりながら見習いとして漆器を作り始めた。','1. 二〇二七年四月、青波町の木工房で、佐伯蓮さんは師匠に教わりながら<u>見習い</u>として漆器を作り始めた。',1,NULL,1.00,NULL,'「見習い」の正しい読み方は「みならい」で、師匠から技術を学ぶ人を指します。',1);
