INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,1,'青波町の木工所で、見習いの蓮は親方の岳人から、売り物にならない木片で毎朝練習するよう言われていた。蓮は最初、完成品を作らせてもらえないことに不満だった。しかし三か月後、木の癖を読む力がつき、初めて任された小箱を予定より早く仕上げた。岳人は、技術だけでなく、材料を無駄にしない姿勢を身につけてほしかったのである。','青波町の木工所で、見習いの蓮は親方の岳人から、売り物にならない木片で毎朝練習するよう言われていた。蓮は最初、完成品を作らせてもらえないことに不満だった。しかし三か月後、木の癖を読む力がつき、初めて任された小箱を予定より早く仕上げた。岳人は、技術だけでなく、材料を無駄にしない姿勢を身につけてほしかったのである。',NULL,1);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,2,'山見市では、利用者の減少した路線バスを廃止する案が出ていた。市は高齢者への聞き取りを行い、病院へ行く朝の便だけは乗客が多いことを確認した。そこで、来年四月から昼の二便を減らす一方、朝の便を病院の入口まで延長することにした。運転手不足のため、全便を残すことはできなかったという。','山見市では、利用者の減少した路線バスを廃止する案が出ていた。市は高齢者への聞き取りを行い、病院へ行く朝の便だけは乗客が多いことを確認した。そこで、来年四月から昼の二便を減らす一方、朝の便を病院の入口まで延長することにした。運転手不足のため、全便を残すことはできなかったという。',NULL,2);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,3,'白栞市立博物館の企画展では、名の知られた画家の作品ではなく、町の住民が長年保管してきた道具や手紙が展示された。学芸員の美緒は、貴重さを競う展覧会にしたいのではなく、同じ地域で暮らした人々の選択を来館者に想像してほしいと話す。そのため、各資料のそばには、提供者から聞いた思い出も添えられている。','白栞市立博物館の企画展では、名の知られた画家の作品ではなく、町の住民が長年保管してきた道具や手紙が展示された。学芸員の美緒は、貴重さを競う展覧会にしたいのではなく、同じ地域で暮らした人々の選択を来館者に想像してほしいと話す。そのため、各資料のそばには、提供者から聞いた思い出も添えられている。',NULL,3);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,4,'星浦神社の秋祭りでは、毎年ボランティアが屋台の準備と子どもの案内を担当している。今年は申し込みが例年の半分しかなく、実行委員会は屋台を減らす案も考えた。ところが高校生が、作業を一時間ずつ交代する方式を提案した。参加者の負担が軽くなるなら協力できるという人が増え、屋台の数を変えずに開催できることになった。','星浦神社の秋祭りでは、毎年ボランティアが屋台の準備と子どもの案内を担当している。今年は申し込みが例年の半分しかなく、実行委員会は屋台を減らす案も考えた。ところが高校生が、作業を一時間ずつ交代する方式を提案した。参加者の負担が軽くなるなら協力できるという人が増え、屋台の数を変えずに開催できることになった。',NULL,4);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,5,'霧野町の古書店「頁の窓」は、店主の千代が集めた郷土資料を自由に読める小さな閲覧室を開いた。資料は古く、持ち出しは禁止だが、希望者には店員が複写を手伝う。千代は本を売るだけでは町の記憶が途切れると考え、若い世代にも資料の存在を知ってほしいという。利用者が少ない日も、閲覧室を閉める予定はない。','霧野町の古書店「頁の窓」は、店主の千代が集めた郷土資料を自由に読める小さな閲覧室を開いた。資料は古く、持ち出しは禁止だが、希望者には店員が複写を手伝う。千代は本を売るだけでは町の記憶が途切れると考え、若い世代にも資料の存在を知ってほしいという。利用者が少ない日も、閲覧室を閉める予定はない。',NULL,5);
