INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,9,'星川町地域資料館では、2026年10月12日から11月8日まで、木工職人・藤田源一さんと弟子の黒田葵さんの作品展「木の記憶」を開く。黒田さんは10月25日に旧星川小学校で行われる町の収穫祭にも参加し、午前中はボランティアとして来場者の案内をする予定である。収穫祭の実行委員長である高瀬さんは、黒田さんに木工の実演もしてほしいと考えているが、午前中は会場の案内係が足りないため、黒田さんを実演に回すことはできない。
