INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,1,'1. 七月三日、白雲国立公園の青葉岳ビジターセンターで、珍しい高山植物の写真が展示された。','1. 七月三日、白雲国立公園の青葉岳ビジターセンターで、珍しい高山植物の写真が<u>展示</u>された。',2,NULL,1.00,NULL,'「展示」の読み方は、写真や作品などを見せるという意味の「てんじ」です。',1);
