INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,1,'青葉県月見野町は、山に囲まれた小さな町である。町には、昔から藍染めを続けている「高瀬工房」があり、2026年4月、森川葵さんが職人の高瀬源一さんに弟子入りした。森川さんは、毎朝、工房を掃除する【1】、高瀬さんからその日の作業を教えてもらった。町営バスは本数が少なく、工房へ通う人には不便だった。そのため、町役場は住民の意見を聞き、6月1日から駅と工房を結ぶ朝の便を一つ増やす【2】。9月10日からは、月見野工芸博物館で高瀬工房の作品展が開かれた。博物館では、作品を展示する【3】、染料を作る様子を撮影した写真も紹介することにした。展示会の最終日には、町のボランティアが行う「月見野灯り祭」も開かれた。天気予報では雨の可能性があったが、実行委員会は、雨が降った【4】、祭りは予定どおり行うと決めていた。森川さんは祭りで来場者に藍染めを説明し、子どもたちには小さな布を染める体験をしてもらった。最初は緊張していたが、祭りが終わるころには、一人で小さな皿を完成させられる【5】。','青葉県月見野町は、山に囲まれた小さな町である。町には、昔から藍染めを続けている「高瀬工房」があり、2026年4月、森川葵さんが職人の高瀬源一さんに弟子入りした。森川さんは、毎朝、工房を掃除する【1】、高瀬さんからその日の作業を教えてもらった。町営バスは本数が少なく、工房へ通う人には不便だった。そのため、町役場は住民の意見を聞き、6月1日から駅と工房を結ぶ朝の便を一つ増やす【2】。9月10日からは、月見野工芸博物館で高瀬工房の作品展が開かれた。博物館では、作品を展示する【3】、染料を作る様子を撮影した写真も紹介することにした。展示会の最終日には、町のボランティアが行う「月見野灯り祭」も開かれた。天気予報では雨の可能性があったが、実行委員会は、雨が降った【4】、祭りは予定どおり行うと決めていた。森川さんは祭りで来場者に藍染めを説明し、子どもたちには小さな布を染める体験をしてもらった。最初は緊張していたが、祭りが終わるころには、一人で小さな皿を完成させられる【5】。',NULL,1);
INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,@mock_passage_1,NULL,19,'19. 【1】','19. 【1】',1,NULL,1.00,NULL,'「たびに」 diễn tả việc cứ mỗi lần Morikawa dọn dẹp thì cô lại được Takase chỉ dẫn.',1);
