INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,2,'青葉町の木工所「森谷工房」では、十六歳のミナトが職人の森谷さんに弟子入りした。最初、ミナトは新しい家具を早く作りたかった。しかし、森谷さんは壊れた机を捨てず、時間をかけて直した。持ち主が喜ぶ姿を見たミナトは、古い物を生かす仕事の大切さを知った。','青葉町の木工所「森谷工房」では、十六歳のミナトが職人の森谷さんに弟子入りした。最初、ミナトは新しい家具を早く作りたかった。しかし、森谷さんは壊れた机を捨てず、時間をかけて直した。持ち主が喜ぶ姿を見たミナトは、古い物を生かす仕事の大切さを知った。',NULL,2);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,3,'三日月市では、四月一日から町営バスの時刻が変わる。病院へ行く人が多い午前中は便を増やし、利用者の少ない午後三時の便はなくすことになった。また、新しい時刻表は駅だけでなく、各バス停と市役所でも配られる。市は高齢者が困らないよう、変更を二週間前から知らせている。','三日月市では、四月一日から町営バスの時刻が変わる。病院へ行く人が多い午前中は便を増やし、利用者の少ない午後三時の便はなくすことになった。また、新しい時刻表は駅だけでなく、各バス停と市役所でも配られる。市は高齢者が困らないよう、変更を二週間前から知らせている。',NULL,3);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,4,'白浜郷土館では、六月十日から「海辺の暮らし」展を開く。展示する漁師の道具の一部は、遠い波野村の家から借りたものだ。予定では五月に届くはずだったが、道具の状態を調べる作業に時間がかかった。そのため、展示の開始日は変えず、説明文の印刷だけを一週間遅らせることになった。','白浜郷土館では、六月十日から「海辺の暮らし」展を開く。展示する漁師の道具の一部は、遠い波野村の家から借りたものだ。予定では五月に届くはずだったが、道具の状態を調べる作業に時間がかかった。そのため、展示の開始日は変えず、説明文の印刷だけを一週間遅らせることになった。',NULL,4);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,5,'星川町の夏祭りでは、今年から外国人にも楽しんでもらえるよう、案内所に英語と韓国語の説明を置く。ボランティアのアヤは、祭りの前日に説明を袋へ入れる仕事を担当する予定だった。しかし、台風で前日の準備が中止になったため、当日の午前九時に公民館へ集まり、作業を始めることになった。','星川町の夏祭りでは、今年から外国人にも楽しんでもらえるよう、案内所に英語と韓国語の説明を置く。ボランティアのアヤは、祭りの前日に説明を袋へ入れる仕事を担当する予定だった。しかし、台風で前日の準備が中止になったため、当日の午前九時に公民館へ集まり、作業を始めることになった。',NULL,5);
INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,@mock_passage_1,NULL,24,'24. ミナトが木工所に弟子入りしてよかったと思ったのは、なぜですか。','24. ミナトが木工所に弟子入りしてよかったと思ったのは、なぜですか。',2,NULL,3.00,NULL,'ミナト cảm nhận được ý nghĩa của việc tận dụng đồ cũ sau khi thấy người chủ vui vì chiếc bàn được sửa lại.',1);
