INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,1,'三月二十三日、私は白川線に乗って、青葉町へ行きました。青葉町駅の近くにある「こもれび工房」で、午前十時から陶芸教室がありました。陶芸教室に参加する【1】、名前と電話番号を紙に書きました。先生は湯のみの作り方を説明しました。私は先生の説明【2】、小さな湯のみを作りました。午後は「ひなた市民図書館」へ行き、春の本を一冊借りました。返却日は来週の金曜日なので、その日【3】に本を返します。夜は駅の近くで「春の花見灯り祭り」がありました。雨が降って【4】、祭りは予定どおり行われました。祭りのあと、帰りの電車が来る【5】、駅の売店で家族へのお菓子を買いました。楽しい一日でした。','三月二十三日、私は白川線に乗って、青葉町へ行きました。青葉町駅の近くにある「こもれび工房」で、午前十時から陶芸教室がありました。陶芸教室に参加する【1】、名前と電話番号を紙に書きました。先生は湯のみの作り方を説明しました。私は先生の説明【2】、小さな湯のみを作りました。午後は「ひなた市民図書館」へ行き、春の本を一冊借りました。返却日は来週の金曜日なので、その日【3】に本を返します。夜は駅の近くで「春の花見灯り祭り」がありました。雨が降って【4】、祭りは予定どおり行われました。祭りのあと、帰りの電車が来る【5】、駅の売店で家族へのお菓子を買いました。楽しい一日でした。',NULL,1);
