INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,2,'青空町の文化センターでは、6月8日（土）に「木の小物作り」をします。時間は午前10時から12時までで、参加費は500円です。小学生は一人で参加できません。使いたい色のペンと、飲み物を持ってきてください。申し込みは6月5日までです。','青空町の文化センターでは、6月8日（土）に「木の小物作り」をします。時間は午前10時から12時までで、参加費は500円です。小学生は一人で参加できません。使いたい色のペンと、飲み物を持ってきてください。申し込みは6月5日までです。',NULL,2);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,3,'星見市立みどり図書館は、7月20日から8月31日まで、毎日午前9時から午後6時まで開いています。ただし、月曜日は休みです。夏休みの本は一人5冊まで借りられ、2週間後の同じ曜日に返します。8月10日は午後3時から読み聞かせがあります。','星見市立みどり図書館は、7月20日から8月31日まで、毎日午前9時から午後6時まで開いています。ただし、月曜日は休みです。夏休みの本は一人5冊まで借りられ、2週間後の同じ曜日に返します。8月10日は午後3時から読み聞かせがあります。',NULL,3);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,4,'川辺町の秋祭りは、9月15日（日）に川辺公園で行われます。朝9時から午後4時まで、地元の店が食べ物を売ります。午後1時には太鼓の演奏があり、午後2時から子どもの踊りが始まります。雨のときは体育館に変更します。','川辺町の秋祭りは、9月15日（日）に川辺公園で行われます。朝9時から午後4時まで、地元の店が食べ物を売ります。午後1時には太鼓の演奏があり、午後2時から子どもの踊りが始まります。雨のときは体育館に変更します。',NULL,4);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,5,'リナさんは10月3日、風見駅を午前8時20分に出る電車に乗り、星川駅へ行きます。切符は駅の機械で買い、片道2,400円です。大きい荷物があるので、風見駅のロッカーに荷物を入れてから、7番線へ行きます。駅で昼ご飯を買う予定です。','リナさんは10月3日、風見駅を午前8時20分に出る電車に乗り、星川駅へ行きます。切符は駅の機械で買い、片道2,400円です。大きい荷物があるので、風見駅のロッカーに荷物を入れてから、7番線へ行きます。駅で昼ご飯を買う予定です。',NULL,5);
