INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,26,'26. 青葉町の木工所で、ユウタさんは二月から職人の佐々木さんに習っています。仕事を手伝いながら、木の皿の作り方を覚えています。「仕事を手伝いながら」とだいたい同じ意味のものはどれですか。','26. 青葉町の木工所で、ユウタさんは二月から職人の佐々木さんに習っています。<u>仕事を手伝いながら</u>、木の皿の作り方を覚えています。「仕事を手伝いながら」とだいたい同じ意味のものはどれですか。',3,NULL,1.00,NULL,'「仕事を手伝いながら」は「仕事を手伝っている間に」と同じ意味です。',1);
