INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,1,'青葉町は小さい町ですが、毎年いろいろな行事があります。今年の三月【1】、私は「青葉工房」で竹細工の職人、森川さんの弟子になりました。工房へ行くときは、町のバス【2】行きます。青葉町のバスは一時間に一本しかありませんが、朝七時のバスは工房の近くに止まります。五月十日【3】六月二日まで、青葉町歴史館で「昔の道具展」が開かれます。森川さんの竹かごも展示されるので、私は毎日少しずつ準備をしています。六月十五日の町の祭りでは、私たちはボランティアとして参加します。祭りの前に、ボランティアのみんな【4】公園を掃除します。実行委員会は「雨が降っても、祭りを【5】」と発表しました。','青葉町は小さい町ですが、毎年いろいろな行事があります。今年の三月【1】、私は「青葉工房」で竹細工の職人、森川さんの弟子になりました。工房へ行くときは、町のバス【2】行きます。青葉町のバスは一時間に一本しかありませんが、朝七時のバスは工房の近くに止まります。五月十日【3】六月二日まで、青葉町歴史館で「昔の道具展」が開かれます。森川さんの竹かごも展示されるので、私は毎日少しずつ準備をしています。六月十五日の町の祭りでは、私たちはボランティアとして参加します。祭りの前に、ボランティアのみんな【4】公園を掃除します。実行委員会は「雨が降っても、祭りを【5】」と発表しました。',NULL,1);
