INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,6,'青葉町では、木工職人の佐野健一さんが、家具を作る仕事をしています。2026年4月、高校を卒業したリオさんが、佐野さんの工房で見習いを始めました。工房の仕事は水曜日から日曜日まで、朝9時から午後4時までです。最初の一か月、リオさんは工房の掃除をしたり、道具をきれいにしたりします。6月からは、佐野さんに教えてもらいながら、小さい木の箱を作ります。
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,7,'星見市歴史館では、2026年6月10日から7月21日まで、「海と町の百年」という特別展を開きます。昔の船の写真や、港で使われていた道具を見ることができます。歴史館は毎週月曜日が休みです。入館料は大人300円ですが、高校生以下は無料です。
INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,@mock_passage_1,NULL,30,'30. 木曜日の朝、リオさんは工房へどうやって行きますか。','30. 木曜日の朝、リオさんは工房へどうやって行きますか。',2,NULL,3.00,NULL,'Vì nhà của Rio ở xa và chuyến xe buýt buổi sáng đến trước giờ làm 15 phút, nên sáng thứ năm cậu ấy đi bằng xe Chano-ki.',1);
