INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,25,'25. さくら町の「にじ工房」で、ミナさんは先生といっしょに小さい花びんを作りました。ミナさんは自分で作りました。 「自分で作りました」と同じ意味の文はどれですか。','25. さくら町の「にじ工房」で、ミナさんは先生といっしょに小さい花びんを作りました。ミナさんは<u>自分で作りました</u>。 「自分で作りました」と同じ意味の文はどれですか。',2,NULL,1.00,NULL,'「自分で作りました」 có nghĩa là Mina tự tay làm nên đáp án 2 là đúng.',1);
