INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,27,'27. 山川村の秋まつりは、毎年十月五日にあります。今年は星川広場で行います。秋まつりは年に一度あります。 「年に一度」と同じ意味の言葉はどれですか。','27. 山川村の秋まつりは、毎年十月五日にあります。今年は星川広場で行います。秋まつりは<u>年に一度</u>あります。 「年に一度」と同じ意味の言葉はどれですか。',1,NULL,1.00,NULL,'「年に一度」 có nghĩa là mỗi năm một lần, nên đáp án 1 là đúng.',3);
