INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,1,'四月二十日（土曜日）、ミナさんは青川駅から電車【1】花町駅へ行きました。花町駅で降りて、さくら町公民館の「手作り教室」に参加しました。先生のユウさんは「木の小さい鳥を作りましょう」と言いました。ミナさんは友だちのケンさん【2】いっしょに鳥を作りました。教室は二時間【3】終わりました。教室のあと、駅の近くの「ひかり町立図書館」へ行きました。図書館で日本の春の祭りの本【4】二冊借りました。夕方、駅前の春祭りへ行きました。祭りは午後五時【5】始まりました。ミナさんは祭りでおいしいだんごを食べて、夜、電車で家へ帰りました。','四月二十日（土曜日）、ミナさんは青川駅から電車【1】花町駅へ行きました。花町駅で降りて、さくら町公民館の「手作り教室」に参加しました。先生のユウさんは「木の小さい鳥を作りましょう」と言いました。ミナさんは友だちのケンさん【2】いっしょに鳥を作りました。教室は二時間【3】終わりました。教室のあと、駅の近くの「ひかり町立図書館」へ行きました。図書館で日本の春の祭りの本【4】二冊借りました。夕方、駅前の春祭りへ行きました。祭りは午後五時【5】始まりました。ミナさんは祭りでおいしいだんごを食べて、夜、電車で家へ帰りました。',NULL,1);
