INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,2,'あおば町の手作り教室は、六月十五日（土曜日）の午前十時から十二時までです。山田さんは妹と行きます。先生は木の小さい箱を作ります。材料は教室にあります。この教室は楽しいです。','あおば町の手作り教室は、六月十五日（土曜日）の午前十時から十二時までです。山田さんは妹と行きます。先生は木の小さい箱を作ります。材料は教室にあります。この教室は楽しいです。',NULL,2);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,3,'みどり市民図書館は、毎週水曜日が休みです。七月三日（水曜日）は休みですが、四日（木曜日）は朝九時から午後五時まで開いています。リナさんは四日に本を返します。','みどり市民図書館は、毎週水曜日が休みです。七月三日（水曜日）は休みですが、四日（木曜日）は朝九時から午後五時まで開いています。リナさんは四日に本を返します。',NULL,3);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,4,'八月十日の土曜日、川辺町で夏祭りがあります。ケンさんは星川駅から電車に乗ります。電車は午後三時に出て、青空駅に三時二十分に着きます。祭りは駅の近くです。','八月十日の土曜日、川辺町で夏祭りがあります。ケンさんは星川駅から電車に乗ります。電車は午後三時に出て、青空駅に三時二十分に着きます。祭りは駅の近くです。',NULL,4);
INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,@mock_passage_1,NULL,21,'21. 山田さんはだれと手作り教室へ行きますか。','21. 山田さんはだれと手作り教室へ行きますか。',1,NULL,3.00,NULL,'Đoạn văn nói rõ Yamada đi cùng em gái nên đáp án 1 là đúng.',1);
