INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,5,'みどり町の さくら図書館では、4月12日（土曜日）に 紙の花の教室があります。町の先生が、図書館の一階で 教えます。教室は 午前10時から 12時までです。来る人は、はさみと 赤い紙を 持ってきてください。教室のあとで、図書館の本を読むこともできます。','みどり町の さくら図書館では、4月12日（土曜日）に 紙の花の教室があります。町の先生が、図書館の一階で 教えます。教室は 午前10時から 12時までです。来る人は、はさみと 赤い紙を 持ってきてください。教室のあとで、図書館の本を読むこともできます。',NULL,5);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,6,'ゆうたさんは、7月20日に 星まつりへ 行きます。朝8時15分に 北川駅から 青葉線の電車に乗ります。9時に 月見駅に着いて、駅から 月見公園まで歩きます。星まつりは 午前10時から 午後4時までです。ゆうたさんは、まつりのあと、月見駅から 4時30分の電車に乗って、5時に 北川駅へ帰ります。','ゆうたさんは、7月20日に 星まつりへ 行きます。朝8時15分に 北川駅から 青葉線の電車に乗ります。9時に 月見駅に着いて、駅から 月見公園まで歩きます。星まつりは 午前10時から 午後4時までです。ゆうたさんは、まつりのあと、月見駅から 4時30分の電車に乗って、5時に 北川駅へ帰ります。',NULL,6);
INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,@mock_passage_1,NULL,24,'24. 紙の花の教室に来る人は、何を持ってきますか。','24. 紙の花の教室に来る人は、何を持ってきますか。',2,NULL,3.00,NULL,'Đoạn văn yêu cầu người tham gia mang kéo và giấy đỏ, nên đáp án 2 đúng.',1);
