INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,NULL,NULL,27,'27. 八月三日、山川市場で、ミナさんは三百円のおにぎりを買い、五百円を出しました。店の人からおつりをもらいました。「おつり」と同じ意味のものはどれですか。','27. 八月三日、山川市場で、ミナさんは三百円のおにぎりを買い、五百円を出しました。店の人から<u>おつり</u>をもらいました。「おつり」と同じ意味のものはどれですか。',3,NULL,1.00,NULL,'「おつり」 là số tiền được trả lại sau khi đưa nhiều tiền hơn giá hàng, nên đáp án là 「返ってくるお金」.',3);
