INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,2,'五月二十日、ユキさんは青山国立公園のビジターセンターへ行きました。センターは午前九時から午後四時までです。山の写真を見て、地図をもらいました。入るお金はいりません。','五月二十日、ユキさんは青山国立公園のビジターセンターへ行きました。センターは午前九時から午後四時までです。山の写真を見て、地図をもらいました。入るお金はいりません。',NULL,2);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,3,'土曜日の朝、みどり町のリサイクル会が中央公園であります。午前八時に始まり、十時に終わります。ペットボトルと古い新聞を持ってきてください。雨の日は東小学校でします。','土曜日の朝、みどり町のリサイクル会が中央公園であります。午前八時に始まり、十時に終わります。ペットボトルと古い新聞を持ってきてください。雨の日は東小学校でします。',NULL,3);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,4,'日曜日、ケンさんは川町の昔の市場へ行きました。赤い店で北山の米のおもちを買いました。店の人は「これはこの町の冬の食べ物です」と言いました。おもちは一つ百円でした。','日曜日、ケンさんは川町の昔の市場へ行きました。赤い店で北山の米のおもちを買いました。店の人は「これはこの町の冬の食べ物です」と言いました。おもちは一つ百円でした。',NULL,4);
