INSERT INTO jlpt_mondai(part_id,mondai_number,format_code,instruction_html,audio_url,order_index) VALUES (@mock_part_id,5,'reading_medium','問題5：文章を読んで、質問に答えなさい。',NULL,5);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,5,'みどり山国立公園のビジターセンターからのお知らせです。六月十五日（土）は、午前九時から午後四時まで開いています。午前十一時には、近くの村の人が作った そばと りんごジュースの試食会があります。試食会は一人一回、無料です。公園の地図も、センターでもらうことができます。','みどり山国立公園のビジターセンターからのお知らせです。六月十五日（土）は、午前九時から午後四時まで開いています。午前十一時には、近くの村の人が作った そばと りんごジュースの試食会があります。試食会は一人一回、無料です。公園の地図も、センターでもらうことができます。',NULL,5);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,6,'青葉町のリサイクルの日は、九月八日（日）です。午前九時から十一時まで、青葉公民館の前で、びん、かん、古い新聞を集めます。参加する人は、きれいにした物を袋に入れて持ってきてください。午前十一時から午後三時までは、同じ場所で秋の市場があります。山川地方の人が、みそ、りんご、そばを売ります。','青葉町のリサイクルの日は、九月八日（日）です。午前九時から十一時まで、青葉公民館の前で、びん、かん、古い新聞を集めます。参加する人は、きれいにした物を袋に入れて持ってきてください。午前十一時から午後三時までは、同じ場所で秋の市場があります。山川地方の人が、みそ、りんご、そばを売ります。',NULL,6);
INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,@mock_passage_1,NULL,24,'24. 午前十一時に、ビジターセンターで何がありますか。','24. 午前十一時に、ビジターセンターで何がありますか。',3,NULL,3.00,NULL,'Đoạn văn nói rõ lúc 11 giờ có buổi dùng thử mì soba và nước táo.',1);
