INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,2,'青空町の木工店で、ゆいさんは四月から職人の田中さんに習っています。毎朝、店を掃除して、木のいすを作ります。五月十日は町のお祭りで、ゆいさんのいすも店の前に並びます。','青空町の木工店で、ゆいさんは四月から職人の田中さんに習っています。毎朝、店を掃除して、木のいすを作ります。五月十日は町のお祭りで、ゆいさんのいすも店の前に並びます。',NULL,2);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,3,'星川市の小さなバスは、六月一日から夏の時刻表を使います。朝は七時と九時、駅から山田村へ行きます。日曜日はバスがありません。駅の近くに新しい時刻表があります。','星川市の小さなバスは、六月一日から夏の時刻表を使います。朝は七時と九時、駅から山田村へ行きます。日曜日はバスがありません。駅の近くに新しい時刻表があります。',NULL,3);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,4,'白浜博物館で、八月三日から昔の祭りの写真展があります。お金はいりません。八月十日は博物館の前で子どもの祭りがあります。ボランティアの人は朝九時に来てください。','白浜博物館で、八月三日から昔の祭りの写真展があります。お金はいりません。八月十日は博物館の前で子どもの祭りがあります。ボランティアの人は朝九時に来てください。',NULL,4);
INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,@mock_passage_1,NULL,21,'21. ゆいさんは毎朝何をしますか。','21. ゆいさんは毎朝何をしますか。',1,NULL,3.00,NULL,'Đoạn văn nói rằng mỗi sáng Yui dọn dẹp cửa hàng và làm ghế.',1);
