INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,5,'星川市の川田町には、「ひなた工房」という小さな店があります。ここでは、木のおもちゃを作っています。ミナさんは四月十日から、先生の大野さんに木のおもちゃの作り方を習っています。ミナさんは火曜日から土曜日まで、朝九時から工房で仕事をします。駅前から工房の前まで行く青いバスは、朝八時十分に出ます。ミナさんはいつもそのバスに乗ります。町のバスは一日に三本だけです。','星川市の川田町には、「ひなた工房」という小さな店があります。ここでは、木のおもちゃを作っています。ミナさんは四月十日から、先生の大野さんに木のおもちゃの作り方を習っています。ミナさんは火曜日から土曜日まで、朝九時から工房で仕事をします。駅前から工房の前まで行く青いバスは、朝八時十分に出ます。ミナさんはいつもそのバスに乗ります。町のバスは一日に三本だけです。',NULL,5);
INSERT INTO jlpt_passage(part_id,source_passage_id,passage_ja,passage_html,passage_vi,order_index) VALUES (@mock_part_id,6,'白浜市立海の博物館では、六月三日から七月二十一日まで、「海の町の昔」という展示をします。昔の船の写真や、漁師が使った道具を見ることができます。博物館は月曜日が休みです。七月十四日には、博物館の前の広場で夏の祭りがあります。ボランティアの人たちは朝九時に集まって、入口で来た人に博物館と祭りの地図を配ります。祭りは午後四時までです。','白浜市立海の博物館では、六月三日から七月二十一日まで、「海の町の昔」という展示をします。昔の船の写真や、漁師が使った道具を見ることができます。博物館は月曜日が休みです。七月十四日には、博物館の前の広場で夏の祭りがあります。ボランティアの人たちは朝九時に集まって、入口で来た人に博物館と祭りの地図を配ります。祭りは午後四時までです。',NULL,6);
INSERT INTO jlpt_question(mondai_id,passage_id,question_type_id,question_number,question_text,question_html,correct_option,correct_order,score,image_url,explanation,order_index) VALUES (@mock_mondai_id,@mock_passage_1,NULL,24,'24. ミナさんは朝、どうやって工房へ行きますか。','24. ミナさんは朝、どうやって工房へ行きますか。',2,NULL,3.00,NULL,'Đoạn văn nói rằng mỗi sáng Mina đi xe buýt màu xanh từ trước nhà ga đến xưởng.',1);
